package storage

import (
	"context"
	"io"
	"runtime"
	"testing"
)

// patternReader yields n generated bytes without holding them in memory.
type patternReader struct{ n, off int64 }

func (r *patternReader) Read(p []byte) (int, error) {
	if r.off >= r.n {
		return 0, io.EOF
	}
	if rem := r.n - r.off; int64(len(p)) > rem {
		p = p[:rem]
	}
	for i := range p {
		p[i] = byte(r.off + int64(i))
	}
	r.off += int64(len(p))
	return len(p), nil
}

// TestPutMemoryIsBounded is deliberately not parallel: TotalAlloc is
// process-wide, and parallel tests only run after all sequential ones.
func TestPutMemoryIsBounded(t *testing.T) {
	const size = 64 << 20
	s, _ := newStore(t, nil)
	runtime.GC()
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	info, err := s.Put(context.Background(), "b", "big", &patternReader{n: size}, size, PutOptions{})
	runtime.ReadMemStats(&after)
	if err != nil || info.Size != size {
		t.Fatalf("Put = (%+v, %v)", info, err)
	}
	if grew := after.TotalAlloc - before.TotalAlloc; grew >= 4<<20 {
		t.Fatalf("Put of %d bytes allocated %d bytes, want < 4 MiB", size, grew)
	}
}
